fn main() -> i64 with IO, Mut, Div, Panic {
    println("=== MatNM Dynamic Matrix Tests ===")
    println("")

    var passed: i64 = 0
    var failed: i64 = 0

    // T1
    print("T1: Identity * vector = vector... ")
    if test_identity_mul_vec() == 1 {
        println("PASS")
