//@ run-pass
// GENERAL 16-component Cayley-Dickson product over Q -- ALL 16 components, ARBITRARY rational
// coefficients (not just the canonical +/-1 channel). Key: the common-denominator representation
// (a rational sedenion = 16 integer numerators A[16] over one common denom Ad) reduces the rational
// 16-comp product to an INTEGER 16-comp product of numerators, den = Ad*Bd -- so NO [Rational;16]
// by-value aggregate (the #637 wall is CIRCUMVENTED, not hit). v1: i64 numerators (rational coeffs
// with num/den up to ~1e8; output fits i64). Cross-verified element-wise vs scripts/research/cd16_oracle.py.
// Bigint numerators (unbounded coeffs) is the next step. Emits DEN/COMP lines for the gate.
// numerators A[16] over a common denom Ad. (a*b)[k] = (sum_{i^j=k} sigma(i,j) A[i] B[j]) / (Ad*Bd).
// So the rational 16-comp product reduces to an INTEGER 16-comp product of numerators. v1: i64.
fn cd_sigma_c(a: i64, b: i64, bits: i64) -> i64 with Mut, Panic, Div {
    if a == 0 || b == 0 { return 1 }
    if bits <= 1 { return 0 - 1 }
    let half = 1 << (bits - 1)
    let a_hi = if a >= half { 1 } else { 0 }
